select id, file_id, frame_type, frame_time, frame_seq, ioa, raw_value, quantity_name, quantity_unit
from iec104_data_point

    AND file_id = #{fileId}
    AND frame_type = #{frameType}
    AND ioa = #{ioa}

order by frame_seq, ioa

